1: // arena.h - locate the sm120 driver-internal trap-handler arena (header only).
2: //
3: // See FINDINGS_ZH.md v0.1 for how this was derived:
4: //   * the tools export table (CU_ETID_ToolsTrapHandler slot 20) reports a
5: //     0x1300-byte image whose [0,0xA00) is the relocated `.text.do_pause`
6: //     plugin routine from libcuda;
7: //   * its relocation slots expose scratchpad / trap_reason_table, and the arena
8: //     base is trap_reason_table - 0xc38300 on driver 595.99.02;
