24:                 printf("[patch] fingerprint mismatch at +%#x\n", i * 16); return false;
25:             }
26:         cave = I.tools_pc + 0xa00;
27:         memcpy(orig, &I.handler[0x390], 16);
28:         printf("[patch] handler=%#llx cave=%#llx preempt_buf=%#llx\n", (unsigned long long)I.handler_va,
