36:         if (cave_bytes > 0x880) { printf("[patch] cave too large\n"); return false; }
37:         cave_backup.resize(w.size());
38:         cuXtraMemcpyDtoH(cave_backup.data(), cave, cave_bytes, 0);
39:         uint64_t o0, o1; memcpy(&o0, &I.handler[0x380], 8); memcpy(&o1, &I.handler[0x388], 8);
40:         uint64_t enc = (cave - 0x100) >> 8, call[2];
41:         call[0] = ((enc & 0xffffffffULL) << 32) | (o0 & 0xffffffffULL);
42:         call[1] = (o1 & ~0xffULL) | ((enc >> 32) & 0xffULL);
43:         size_t a = cuXtraMemcpyHtoD(cave, w.data(), cave_bytes, 0);
44:         size_t b = cuXtraMemcpyHtoD(I.handler_va + 0x390, call, 16, 0);
45:         cuXtraInvalInstrCache(ctx);
46:         uint64_t rb[2]; cuXtraMemcpyDtoH(rb, I.handler_va + 0x390, 16, 0);
47:         installed = a == cave_bytes && b == 16 && rb[0] == call[0] && rb[1] == call[1];
48:         printf("[patch] install cave=%zu hook=%zu verify=%d\n", a, b, (int)installed);
49:         return installed;
50:     }
51:     // rewrite cave body only (hook stays); only safe while no kernel runs
52:     bool rewrite(const std::vector<s120::I> &code) {
53:         auto w = s120::flat(code);
54:         size_t a = cuXtraMemcpyHtoD(cave, w.data(), w.size() * 8, 0);
