60:         cuXtraMemcpyHtoD(I.handler_va + 0x390, orig, 16, 0);
61:         cuXtraMemcpyHtoD(cave, cave_backup.data(), cave_bytes, 0);
62:         cuXtraInvalInstrCache(ctx);
63:         installed = false;
