1: // Tiny hand-assembler for the handful of SM120 SASS forms we inject into the
2: // live trap handler.  Every cave is checked with `nvdisasm -b SM120` before use.
3: #pragma once
4: #include <stdint.h>
5: #include <vector>
6: #include <cstdio>
7: #include <cstdlib>
8: #include <string>
9: 
10: namespace s120 {
11: struct I { uint64_t w0, w1; };
12: // control: stall[41:44] yield[45] wbar[46:48] rbar[49:51] wait[52:57]
13: inline uint64_t ctl(int stall = 15, int wait = 0x3f, int wb = 7, int rb = 7, int yld = 1) {
14:     return ((uint64_t)(stall & 15) | ((uint64_t)yld << 4) | ((uint64_t)wb << 5) | ((uint64_t)rb << 8) |
15:             ((uint64_t)wait << 11)) << 41;
16: }
17: const int RZ = 255;
18: inline I nop() { return {0x0000000000007918ULL, 0x000fc00000000000ULL}; }
19: inline I mov_imm(int rd, uint32_t imm, uint64_t c = ctl()) {
20:     return {((uint64_t)imm << 32) | ((uint64_t)rd << 16) | 0x7802ULL, 0x0000000000000f00ULL | c};
21: }
22: // S2R rd, SR (SR_VIRTUALSMID=0x43, SR_VIRTID=0x03, SR_LANEID=0x00); result via write barrier wb
23: inline I s2r(int rd, int sr, int wb = 0, uint64_t extra = 0) {
24:     return {((uint64_t)rd << 16) | 0x7919ULL, ((uint64_t)sr << 8) | ctl(15, 0x3f, wb) | extra};
25: }
26: inline I cs2r_globaltimer(int rd) { return {((uint64_t)rd << 16) | 0x7805ULL, 0x15200ULL | ctl()}; }
27: // IMAD.WIDE.U32 rd(64) = ra * imm + rc(64)
28: inline I imad_wide_u32_imm(int rd, int ra, uint32_t imm, int rc) {
29:     return {((uint64_t)imm << 32) | ((uint64_t)ra << 24) | ((uint64_t)rd << 16) | 0x7825ULL,
30:             0x00078e0000ULL | (uint64_t)rc | ctl()};
31: }
32: // generic (no descriptor) store: ST.E[.64] [ra+off], rs
33: inline I st_e(int ra, int32_t off, int rs, bool b64 = false) {
34:     return {((uint64_t)(uint32_t)off << 32) | ((uint64_t)ra << 24) | 0x7385ULL,
35:             (b64 ? 0x100b00ULL : 0x100900ULL) | (uint64_t)rs | ctl()};
36: }
37: inline I iadd_imm(int rd, int ra, uint32_t imm) {
38:     return {((uint64_t)imm << 32) | ((uint64_t)ra << 24) | ((uint64_t)rd << 16) | 0x7835ULL, 0x078e0000ULL | ctl()};
39: }
40: inline I ret_r12() { return {0x000000000c087950ULL, 0x003fc00003a00000ULL}; }   // RET.ABS R12 0x20
41: inline I exit_() { return {0x000000000000794dULL, 0x000fea0003800000ULL}; }
42: 
43: inline std::vector<uint64_t> flat(const std::vector<I> &v) {
44:     std::vector<uint64_t> o; for (auto &i : v) { o.push_back(i.w0); o.push_back(i.w1); } return o;
