1: // Experiment: single-SM STOP_TRIGGER / RUN_TRIGGER via direct BAR0 MMIO.
2: #include "bar0.h"
3: #include <cstdio>
4: #include <cstring>
5: #include <ctime>
6: #include <unistd.h>
7: #define NB 30
8: __device__ unsigned smid() { unsigned r; asm volatile("mov.u32 %0, %%smid;" : "=r"(r)); return r; }
9: __global__ void work(volatile unsigned long long *ctr, volatile unsigned *sm, long long cycles) {
10:     extern __shared__ char pad[];
11:     if (threadIdx.x == 0) sm[blockIdx.x] = smid();
12:     long long t0 = clock64();
13:     while (clock64() - t0 < cycles) {
14:         if (threadIdx.x == 0) ctr[blockIdx.x] += 1;
15:         pad[threadIdx.x] = 1;
16:     }
17: }
18: static double now_us() { timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec * 1e6 + t.tv_nsec / 1e3; }
19: int main(int argc, char **argv) {
20:     uint32_t ctl = argc > 1 ? strtoul(argv[1], 0, 0) : 0x504704;   // DBGR_CONTROL0 of target SM
21:     uint32_t st = ctl - 4;                                           // DBGR_STATUS0
22:     int do_run = argc > 2 ? atoi(argv[2]) : 1;
23:     if (bar0_open()) return 1;
24:     unsigned long long *h, *d; unsigned *hs, *ds;
25:     cudaHostAlloc(&h, NB * 8, cudaHostAllocMapped); memset(h, 0, NB * 8); cudaHostGetDevicePointer(&d, h, 0);
26:     cudaHostAlloc(&hs, NB * 4, cudaHostAllocMapped); cudaHostGetDevicePointer(&ds, hs, 0);
27:     int clk; cudaDeviceGetAttribute(&clk, cudaDevAttrClockRate, 0);
28:     cudaFuncSetAttribute(work, cudaFuncAttributeMaxDynamicSharedMemorySize, 80 * 1024);
29:     work<<<NB, 128, 80 * 1024>>>(d, ds, (long long)(2.0 * clk * 1000.0));  // ~2 s
30:     usleep(300000);
31:     printf("before: ctl=%08x st=%08x wvm=%08x\n", rd32(ctl), rd32(st), rd32(ctl + 4));
32:     unsigned long long s0[NB]; memcpy(s0, h, sizeof s0);
33:     uint32_t c = rd32(ctl);
34:     double t0 = now_us();
35:     wr32(ctl, c | 0x80000000u);                 // STOP_TRIGGER
36:     uint32_t s; int n = 0;
37:     do { s = rd32(st); n++; } while (!(s & 0x10) && now_us() - t0 < 100000);
38:     double t1 = now_us();
39:     { double tl = now_us(); uint32_t s2; uint32_t g;
40:       do { s2 = rd32(st); g = rd32(ctl + 0x30); } while ((s2 & 0x10) && now_us() - tl < 2000000);
41:       printf("lock window: %.1f us, then st=%08x ctl=%08x gesr=%08x\n", now_us() - tl, s2, rd32(ctl), g); }
42:     printf("stop: locked_down=%d after %.1f us (%d polls) st=%08x ctl=%08x\n", !!(s & 0x10), t1 - t0, n, s, rd32(ctl));
43:     printf("warp_esr=%08x global_esr=%08x esr_pc=%08x\n", rd32(ctl + 0x2c), rd32(ctl + 0x30), rd32(ctl + 0x34));
44:     unsigned long long s1[NB]; memcpy(s1, h, sizeof s1);
45:     usleep(100000);
46:     printf("delta over 100ms while stopped (block:smid:delta):\n");
47:     for (int i = 0; i < NB; i++) printf("%d:%u:%lld ", i, hs[i], (long long)(h[i] - s1[i])); printf("\n");
48:     printf("after 100ms: st=%08x ctl=%08x gesr=%08x wvm=%08x\n", rd32(st), rd32(ctl), rd32(ctl + 0x30), rd32(ctl + 4));
49:     if (do_run) {
50:         c = rd32(ctl);
51:         double t2 = now_us();
52:         wr32(ctl, (c & ~0x80000000u) | 0x40000000u);   // RUN_TRIGGER
53:         do { s = rd32(st); } while ((s & 0x10) && now_us() - t2 < 100000);
54:         printf("run: locked_down=%d after %.1f us st=%08x ctl=%08x\n", !!(s & 0x10), now_us() - t2, s, rd32(ctl));
55:     }
56:     cudaError_t e = cudaDeviceSynchronize();
57:     printf("kernel result: %s\n", cudaGetErrorString(e));
58:     for (int i = 0; i < NB; i++) printf("%d:%u:%llu ", i, hs[i], h[i]); printf("\n");
59:     return 0;
60: }

