10: __device__ unsigned smid() { unsigned r; asm volatile("mov.u32 %0, %%smid;" : "=r"(r)); return r; }
11: __global__ void work(volatile unsigned long long *ctr, volatile unsigned *sm, long long cycles) {
12:     if (threadIdx.x == 0) sm[blockIdx.x] = smid();
13:     long long t0 = clock64();
14:     while (clock64() - t0 < cycles) if (threadIdx.x == 0) ctr[blockIdx.x] += 1;
15: }
16: __global__ void nop_k() {}
17: static uint64_t ptimer() {
18:     uint32_t hi, lo, hi2;
19:     do { hi = rd32(0x9410); lo = rd32(0x9400); hi2 = rd32(0x9410); } while (hi != hi2);
20:     return ((uint64_t)hi << 32) | lo;
21: }
22: struct Rec { unsigned long long t; unsigned reason, pad; };
23: int main(int argc, char **argv) {
24:     const char *mode = argc > 1 ? argv[1] : "unicast";
