29:     uint64_t rva = (uint64_t)(uintptr_t)rec;
30:     using namespace s120;
31:     std::vector<I> cave = {
32:         mov_imm(3, 0),                        // displaced: MOV R3, RZ (imm 0)
33:         s2r(4, 0x43, 0),                       // S2R R4, SR_VIRTUALSMID
34:         mov_imm(8, (uint32_t)rva), mov_imm(9, (uint32_t)(rva >> 32)),
35:         cs2r_globaltimer(6),
36:         imad_wide_u32_imm(8, 4, sizeof(Rec), 8),
37:         st_e(8, 0, 6, true), st_e(8, 8, 2),
38:         iadd_imm(12, 12, 0x10), ret_r12(),
39:     };
40:     disasm(cave, "/tmp/claude-1000/cave.bin");
41:     if (!P.install(cave)) return 1;
42:     unsigned long long *h; unsigned *hs; cudaHostAlloc(&h, NB * 8, cudaHostAllocMapped); cudaHostAlloc(&hs, NB * 4, cudaHostAllocMapped);
43:     int clk; cudaDeviceGetAttribute(&clk, cudaDevAttrClockRate, 0);
44:     work<<<NB, 128>>>(h, hs, (long long)(1.5 * clk * 1000.0));
45:     usleep(300000);
46:     printf("ptimer=%llu (check vs globaltimer)\n", (unsigned long long)ptimer());
47:     uint32_t reg = strcmp(mode, "bcast") ? 0x504704 : 0x419e84;
48:     uint64_t t0 = ptimer();
49:     wr32(reg, 0x80001c01);
50:     uint64_t t1 = ptimer();
51:     usleep(50000);
52:     printf("stop write took %llu ns; status0(sm0)=%08x ctl=%08x\n", (unsigned long long)(t1 - t0), rd32(0x504700), rd32(0x504704));
53:     int n = 0; uint64_t first = ~0ull, last = 0;
54:     for (int i = 0; i < 256; i++) if (rec[i].t) {
55:         n++; uint64_t d = rec[i].t - t0; if (d < first) first = d; if (d > last) last = d;
56:         printf("  smid %3d reason=%#x trap_at=+%.1f us\n", i, rec[i].reason, (rec[i].t - (double)t0) / 1000.0);
57:     }
58:     printf("SMs trapped: %d  first=+%.1f us last=+%.1f us\n", n, first / 1000.0, last / 1000.0);
59:     cudaError_t e = cudaDeviceSynchronize();
60:     printf("kernel result: %s\n", cudaGetErrorString(e));
61:     P.restore();
62:     nop_k<<<1, 1>>>(); printf("post: %s\n", cudaGetErrorString(cudaDeviceSynchronize()));
63:     return 0;
64: }

